Q: Unable to take screenshot in flutter A: <p>WidgetsBinding.instance.endOfFrame allows you to wait until the current frame is completely drawn.<br />
try this.</p>
<pre><code>Future&lt;Uint8List&gt; _capturePng() async {
    try {
        print('inside');
        RenderRepaintBoundary boundary = _globalKey.currentContext.findRenderObject();
        await WidgetsBinding.instance.endOfFrame; // Add this
        ui.Image image = await boundary.toImage(pixelRatio: 3.0);
        ByteData byteData = await image.toByteData(format: ui.ImageByteFormat.png);
        var pngBytes = byteData.buffer.asUint8List();
        var bs64 = base64Encode(pngBytes);
        print(pngBytes);
        print(bs64);
        setState(() {});
        return pngBytes;
    } catch (e) {
        print(e);
    }
}
</code></pre>
